cd /home/kris/Desktop/trading-research/freqtrade
dk() { tag=$1; shift; mkdir -p results/detail/$tag; docker run --rm --network none --memory 20g --user "$(id -u):$(id -g)" -v "$PWD/user_data:/freqtrade/user_data:ro" -v "$PWD/fut_data:/freqtrade/fut_data:ro" -v "$PWD/${CFG:-config_futures.json}:/freqtrade/config.json:ro" -v "$PWD/docker_offline:/offline:ro" -e PYTHONPATH=/offline -v "$PWD/results/detail/$tag:/freqtrade/user_data/backtest_results" freqtrade-research:latest "$@" --userdir /freqtrade/user_data --datadir /freqtrade/fut_data/binance -c /freqtrade/config.json --strategy-path /freqtrade/user_data/strategies/validate50 2>&1 | grep -vE "chown|FutureWarning|import freqtrade.vendor"; }
S=${S:-RegimeFilterStrategy}; TF=${TF:-1h}; DT=${DT:-5m}; PAIRS=${PAIRS:-"XRP/USDT:USDT BNB/USDT:USDT SOL/USDT:USDT DOGE/USDT:USDT ADA/USDT:USDT TRX/USDT:USDT LINK/USDT:USDT AVAX/USDT:USDT LTC/USDT:USDT DOT/USDT:USDT"}
echo "== LOOKAHEAD"; CFG=config_futures_market.json dk la_$S lookahead-analysis --strategy $S --timeframe $TF --timerange 20220101-20231231 --pairs $PAIRS --max-open-trades 10 | grep -E "bias detected|Error|│" | tail -6
echo "== OOS 2020-2021"; dk oos_$S backtesting --strategy $S --timeframe $TF --timerange 20200101-20211108 --pairs $PAIRS --max-open-trades 10 --breakdown year | grep -E "CAGR|Absolute drawdown|^│ *20(20|21)|Total profit %|Error|No data" | head -14
echo "== DETAIL 2020-2021 $DT"; dk det_$S backtesting --strategy $S --timeframe $TF --timeframe-detail $DT --timerange 20200101-20211108 --pairs $PAIRS --max-open-trades 10 | grep -E "CAGR|Absolute drawdown|Error" | head -4
echo FUT_CHECK_DONE
